/// Pick `count` random questions from the bank
pub fn pick_random_questions(count: usize) -> Vec<String> {
    let mut rng = thread_rng();
    let mut indices: Vec<usize> = (0..QUESTIONS.len()).collect();
    indices.shuffle(&mut rng);

    indices
        .into_iter()
        .take(count.min(QUESTIONS.len()))
        .map(|i| QUESTIONS[i].to_string())
        .collect()
}

/// Get total number of available questions
#[allow(dead_code)]
pub fn total_questions() -> usize {
    QUESTIONS.len()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_pick_random_questions() {
        let qs = pick_random_questions(10);
        assert_eq!(qs.len(), 10);
        // Questions should be unique
        let mut sorted = qs.clone();
        sorted.sort();
        sorted.dedup();
        assert_eq!(sorted.len(), 10);
    }

    #[test]
    fn test_pick_random_questions_empty() {
        let qs = pick_random_questions(0);
        assert_eq!(qs.len(), 0);
    }

    #[test]
    fn test_pick_random_questions_more_than_available() {
        let qs = pick_random_questions(9999);
        assert_eq!(qs.len(), total_questions());
    }

    #[test]
    fn test_total_questions_count() {
        assert!(total_questions() >= 500);
    }
}
